//! Port of pipeline/audit_boundary.go — categorizes every file in the repo
//! as PROGRAMMATIC (regenerated by tools) vs TOOL SOURCE (hand-written code
//! that owns those outputs) vs HAND-AUTHORED, and surfaces the explicit LLM
//! PATCH POINTS inside tool source.
//!
//! The path patterns ARE the source of truth. Patterns are matched
//! first-match-wins and the order is load-bearing: a catch-all placed before
//! a specific rule shadows it — a real bug this file already carried once, so
//! the ordering is asserted by a test rather than left to reading.

use regex::Regex;
use serde::Deserialize;
use serde_json::Value;
use std::collections::HashMap;
use std::path::Path;
use std::sync::{Mutex, OnceLock};

/// A classification pattern. Exactly one of tool/note/owner is set, matching
/// the three kinds. `matches` unifies Go's re/match split (statics cannot
/// call Regex::new, so patterns compile lazily through re_cache).
struct BoundaryPattern {
    matches: Box<dyn Fn(&str) -> bool + Send + Sync>,
    tool: &'static str,
    source: &'static str,
    note: &'static str,
    owner: &'static str,
}

impl BoundaryPattern {
    fn test(&self, path: &str) -> bool {
        (self.matches)(path)
    }
}

fn re_cache(pat: &'static str) -> &'static Regex {
    static CACHE: OnceLock<Mutex<HashMap<&'static str, &'static Regex>>> = OnceLock::new();
    let mut g = CACHE.get_or_init(Default::default).lock().unwrap();
    *g.entry(pat).or_insert_with(|| Box::leak(Box::new(Regex::new(pat).unwrap())))
}

fn one_of(paths: &'static [&'static str]) -> Box<dyn Fn(&str) -> bool + Send + Sync> {
    Box::new(move |p: &str| paths.contains(&p))
}

fn prefix_suffix(
    prefix: &'static str,
    suffixes: &'static [&'static str],
) -> Box<dyn Fn(&str) -> bool + Send + Sync> {
    Box::new(move |p: &str| {
        if !p.starts_with(prefix) {
            return false;
        }
        if suffixes.is_empty() {
            return true;
        }
        suffixes.iter().any(|s| p.ends_with(s))
    })
}

fn rtl_variant(p: &str) -> bool {
    crate::emit::build_rtl::rtl_page_lang(p).is_some()
}

