// ---------------------------------------------------------------- scan

#[derive(Clone, Default, Debug)]
pub struct Classification {
    pub path: String,
    pub kind: String, // programmatic | tool-source | hand-authored | unknown
    pub tool: String,
    pub source: String,
    pub note: String,
    pub owner: String,
}

/// The grouping key for a classification: the tool that owns it, the note
/// describing it, or its owner.
impl Classification {
    fn label(&self) -> &str {
        if !self.tool.is_empty() {
            &self.tool
        } else if !self.note.is_empty() {
            &self.note
        } else if !self.owner.is_empty() {
            &self.owner
        } else {
            ""
        }
    }
}

pub fn classify_path(path: &str) -> Classification {
    for p in programmatic_patterns() {
        if p.test(path) {
            return Classification {
                path: path.to_string(),
                kind: "programmatic".to_string(),
                tool: p.tool.to_string(),
                source: p.source.to_string(),
                note: String::new(),
                owner: String::new(),
            };
        }
    }
    for p in tool_source_patterns() {
        if p.test(path) {
            return Classification {
                path: path.to_string(),
                kind: "tool-source".to_string(),
                note: p.note.to_string(),
                ..Classification::default()
            };
        }
    }
    for p in hand_authored_patterns() {
        if p.test(path) {
            return Classification {
                path: path.to_string(),
                kind: "hand-authored".to_string(),
                owner: p.owner.to_string(),
                ..Classification::default()
            };
        }
    }
    Classification {
        path: path.to_string(),
        kind: "unknown".to_string(),
        ..Classification::default()
    }
}

/// dist/ is deliberately NOT skipped — dist/components/*.html is git-tracked
/// and is the live library output. tools/contracts/out IS skipped: those are
/// runtime oracle artifacts, not repo source.
const AUDIT_SKIP: [&str; 4] = [".git", "node_modules", ".upstream", "tools/contracts/out"];

pub fn audit_should_skip(rel: &str) -> bool {
    for s in AUDIT_SKIP {
        if s.contains('/') {
            // path-prefix match
            if rel == s || rel.starts_with(&format!("{}/", s)) {
                return true;
            }
            continue;
        }
        if rel.split('/').any(|seg| seg == s) {
            return true;
        }
    }
    false
}

pub fn audit_walk(root: &Path) -> Result<Vec<String>, String> {
    let mut out: Vec<String> = Vec::new();
    let root_buf = root.canonicalize().unwrap_or_else(|_| root.to_path_buf());
    for e in walkdir::WalkDir::new(&root_buf)
        .into_iter()
        .filter_entry(|entry| {
            // prune a skipped directory the way filepath.SkipDir did: the
            // entry itself is matched on its repo-relative path
            let rel = entry
                .path()
                .strip_prefix(&root_buf)
                .map(|r| r.to_string_lossy().into_owned())
                .unwrap_or_default();
            rel.is_empty() || !audit_should_skip(&rel)
        })
    {
        let Ok(e) = e else { continue }; // an unreadable directory is skipped, as readdirSync's catch did
        if !e.file_type().is_dir() {
            let rel = match e.path().strip_prefix(&root_buf) {
                Ok(r) => r.to_string_lossy().into_owned(),
                Err(_) => continue,
            };
            if rel.is_empty() {
                continue;
            }
            out.push(rel);
        }
    }
    out.sort();
    Ok(out)
}

// ------------------------------------------------------- drift detection

/// Finds tool-generated files MODIFIED relative to HEAD. Untracked files are
/// NOT drift: they are the normal state after `make build`.
pub fn detect_drift(root: &Path, programmatic: &[Classification]) -> Vec<Classification> {
    let modified = git_paths(
        root,
        "--untracked-files=no",
        |x, y| x == b'M' || y == b'M' || x == b'D' || y == b'D',
    );
    programmatic
        .iter()
        .filter(|c| modified.contains_key(&c.path))
        .cloned()
        .collect()
}

/// Runs git status --porcelain and returns the paths whose XY status
/// satisfies keep. A git that is not available yields nothing, as the JS did.
fn git_paths(root: &Path, untracked: &str, keep: fn(u8, u8) -> bool) -> HashMap<String, bool> {
    let mut out = HashMap::new();
    let Ok(b) = std::process::Command::new("git")
        .args(["status", "--porcelain", untracked])
        .current_dir(root)
        .output()
    else {
        return out;
    };
    if !b.status.success() {
        return out;
    }
    for line in String::from_utf8_lossy(&b.stdout).lines() {
        let lb = line.as_bytes();
        if lb.len() < 4 {
            continue;
        }
        if !keep(lb[0], lb[1]) {
            continue;
        }
        let mut rest = &line[3..];
        if let Some(i) = rest.find(" -> ") {
            rest = &rest[i + 4..]; // a rename reports the destination
        }
        out.insert(rest.trim_matches('"').to_string(), true);
    }
    out
}

/// Lists untracked and staged-added paths — everything new since HEAD.
fn detect_new_files(root: &Path) -> Vec<String> {
    let paths = git_paths(root, "--untracked-files=all", |x, y| {
        (x == b'?' && y == b'?') || x == b'A'
    });
    let mut out: Vec<String> = paths
        .into_keys()
        .filter(|p| !p.ends_with('/')) // git lists directories with a trailing slash
        .collect();
    out.sort();
    out
}

